assert.strictEqual(paletteCollectiveContactDecision(pendingFilter,{filterRequestId:'contact-filter-2',filterGeneration:2,activeColorId:'255,0,0,255'}).accept,false,'an older delayed filter response is discarded');
assert.strictEqual(paletteCollectiveContactDecision(pendingFilter,{filterRequestId:'contact-filter-3',filterGeneration:3,activeColorId:'255,0,0,255'}).accept,false,'a mismatched payload cannot satisfy the newest request');
assert.deepStrictEqual(paletteCollectiveContactDecision(pendingFilter,{filterRequestId:'contact-filter-3',filterGeneration:3,activeColorId:'0,0,255,255'}),{accept:true,clearPending:true,lastAcceptedGeneration:3},'only the exact newest filter response may render');
