const pendingPage={sequence:2,lastAcceptedGeneration:0,pending:{pageRequestId:'contact-page-2',pageGeneration:2,page:1}};
assert.strictEqual(paletteCollectivePageDecision(pendingPage,{page:0}).accept,false,'an ordinary page-1 refresh cannot replace a pending page-2 request');
assert.strictEqual(paletteCollectivePageDecision(pendingPage,{pageRequestId:'contact-page-1',pageGeneration:1,page:0}).accept,false,'an older page response cannot replace the newest requested page');
assert.deepStrictEqual(paletteCollectivePageDecision(pendingPage,{pageRequestId:'contact-page-2',pageGeneration:2,page:1}),{accept:true,clearPending:true,lastAcceptedGeneration:2},'only the matching requested page clears the pending navigation');
const pendingPreview={sequence:4,lastAcceptedGeneration:1,pending:{previewRequestId:'current-preview-4',previewGeneration:4,imageId:'newest'}};
assert.strictEqual(paletteCollectivePreviewDecision(pendingPreview,{previewRequestId:'current-preview-3',previewGeneration:3,currentPreview:{imageId:'older'}}).accept,false,'an older delayed image response cannot replace the newest requested main image');
assert.strictEqual(paletteCollectivePreviewDecision(pendingPreview,{previewRequestId:'current-preview-4',previewGeneration:4,currentPreview:{imageId:'wrong'}}).accept,false,'a response for the wrong image cannot satisfy the current preview request');
assert.deepStrictEqual(paletteCollectivePreviewDecision(pendingPreview,{previewRequestId:'current-preview-4',previewGeneration:4,currentPreview:{imageId:'newest'}}),{accept:true,clearPending:true,lastAcceptedGeneration:4},'only the exact newest image response may update the main preview');
assert.strictEqual(paletteCollectivePreviewDecision({...pendingPreview,pending:null},{previewRequestId:'current-preview-4',previewGeneration:4,currentPreview:{imageId:'newest'}}).accept,false,'a canceled image request remains canceled when its delayed response arrives');
